# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import List

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def check_emails(students: List[Student]) -> None:
    """Refuse the whole sheet if anyone has no email."""
    for student in students:
        if not (student.email or "").strip():
            raise ProjectError(
                f"no email for {student.display_name}"
            )


def cells(student: Student) -> List[str]:
    return [
        student.display_name,
        student.section,
        student.email.strip()
    ]


def align(table: List[List[str]]) -> List[str]:
    """Pad every column to the width of its longest cell."""
    widths = [max(map(len, col)) for col in zip(*table)]
    return [
        "  ".join(
            cell.ljust(width)
            for cell, width in zip(row, widths)
        ).rstrip()
        for row in table
    ]


def contact_rows(students: List[Student]) -> List[str]:
    """Rows of name, section and email, sorted by name."""
    if not students:
        raise ProjectError("no students to list")
    check_emails(students)
    ordered = sorted(
        students, key=lambda s: s.display_name.casefold()
    )
    return align([cells(s) for s in ordered])
